/// FreeANDIY's look on upstream's tokens for brightness `b`.
pub fn tokens(b: Brightness, t: Tokens) -> Tokens {
    let t = Tokens {
        radius: 0,
        accent: if t.dark { PINK } else { ROSE },
        accent_strong: ROSE,
        flyout_active: if t.dark { PINK } else { ROSE },
        caption_close: ROSE,
        caption_close_text: PAPER,
        ..t
    };
    match b {
        Brightness::Dark => {
            let ink = |x: f32| mix(BLACK, PAPER, x);
            Tokens {
                app_bar: BLACK,
                panel: mix(BLACK, PAPER, 0.06),
                panel_darker: BLACK,
                tab_strip: BLACK,
                input: mix(BLACK, Color32::BLACK, 0.30),
                input_border: ink(0.30),
                border: mix(BLACK, Color32::BLACK, 0.35),
                divider: ink(0.16),
                text: ink(0.88),
                text_strong: PAPER,
                text_dim: ink(0.66),
                text_disabled: ink(0.40),
                icon: ink(0.85),
                hover: ink(0.16),
                tool_active: mix(BLACK, Color32::BLACK, 0.40),
                row_selected: mix(BLACK, ROSE, 0.45),
                button: ink(0.14),
                button_border: ink(0.42),
                ..t
            }
        }
        Brightness::Light => {
            let ink = |x: f32| mix(PAPER, BLACK, x);
            Tokens {
                app_bar: ink(0.06),
                panel: PAPER,
                panel_darker: ink(0.05),
                tab_strip: ink(0.08),
                input: WHITE,
                input_border: ink(0.30),
                border: ink(0.22),
                divider: ink(0.15),
                text: BLACK,
                text_strong: BLACK,
                text_dim: ink(0.70),
                text_disabled: ink(0.45),
                icon: BLACK,
                hover: ink(0.08),
                tool_active: ink(0.16),
                row_selected: mix(PAPER, YELLOW, 0.60),
                button: ink(0.08),
                button_border: ink(0.42),
                ..t
            }
        }
        _ => t,
    }
}

/// Flat print look for egui's own surfaces: nearly square windows and menus, no soft shadows.
pub fn visuals(v: &mut Visuals) {
    v.window_corner_radius = egui::CornerRadius::same({{shape.radius_sm}});
    v.menu_corner_radius = egui::CornerRadius::same({{shape.radius_sm}});
    v.popup_shadow = egui::epaint::Shadow::NONE;
    v.window_shadow = egui::epaint::Shadow::NONE;
}

/// Translated where a catalog has it (sk, under the `freeandiy` context); constants, so upstream's
/// "every `tl!` literal is translated in every complete catalog" test doesn't require them of
/// upstream's languages.
const LICENCES: &str = "MIT OR Apache-2.0. Fonts: IBM Plex Sans, IBM Plex Mono (OFL). Icons: Lucide (ISC).";
const ATTRIBUTION: &str = "{app} is based on the open-source project {upstream} (© ArtCraft Team and contributors, MIT/Apache-2.0). FreeANDIY is not affiliated with the ArtCraft team.";

const SEAL_PNG: &[u8] = include_bytes!("../../../freeandiy/assets/brand/fa-seal-rose.png");

fn seal(ctx: &Context) -> Option<TextureHandle> {
    let id = Id::new("freeandiy-seal");
    if let Some(tex) = ctx.data(|d| d.get_temp::<TextureHandle>(id)) {
        return Some(tex);
    }
    let img = image::load_from_memory_with_format(SEAL_PNG, image::ImageFormat::Png).ok()?.to_rgba8();
    let image = egui::ColorImage::from_rgba_unmultiplied([img.width() as usize, img.height() as usize], img.as_raw());
    let options = TextureOptions { mipmap_mode: Some(egui::TextureFilter::Linear), ..TextureOptions::LINEAR };
    let tex = ctx.load_texture("freeandiy-seal", image, options);
    ctx.data_mut(|d| d.insert_temp(id, tex.clone()));
    Some(tex)
}

/// The About tab's footer: the licences and fonts, the Free Andy Agency seal and the upstream
/// attribution (MIT/Apache-2.0 require keeping the notices; the ArtCraft brand terms allow naming
/// the origin in plain text).
pub fn about_attribution(ui: &mut Ui) {
    let t = Tokens::get(ui.ctx());
    ui.label(egui::RichText::new(crate::i18n::tr_ctx(crate::i18n::current(), "freeandiy", LICENCES)).size(11.0));
    ui.add_space(10.0);
    ui.vertical_centered(|ui| {
        if let Some(tex) = seal(ui.ctx()) {
            ui.add(egui::Image::new(&tex).fit_to_exact_size(egui::vec2(72.0, 72.0)));
            ui.add_space(6.0);
        }
        let attribution = crate::i18n::fmt(crate::i18n::tr_ctx(crate::i18n::current(), "freeandiy", ATTRIBUTION), &[("app", APP_NAME), ("upstream", UPSTREAM_NAME)]);
        ui.label(egui::RichText::new(attribution).size(11.5).color(t.text_dim));
        ui.add_space(4.0);
        ui.label(egui::RichText::new(format!("© {OWNER}")).size(11.5).color(t.text_dim));
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_seal_decodes() {
        assert!(seal(&Context::default()).is_some());
    }

    #[test]
    fn every_brightness_is_square_with_the_rose_accent() {
        for b in Brightness::ALL {
            let t = Tokens::for_brightness(b);
            assert_eq!(t.radius, 0, "{b:?}");
            assert!(t.accent == ROSE || t.accent == PINK, "{b:?}");
        }
        assert_eq!(Tokens::for_brightness(Brightness::Light).panel, PAPER);
        assert_eq!(Tokens::for_brightness(Brightness::Dark).app_bar, BLACK);
    }
}
